"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def solveNQueens(N):
    board = [[0 for _ in range(N)] for _ in range(N)]
    solutions = []
    def isSafe(board, row, col):
        # Check column
        for i in range(0, row):
            if (board[i][col] == 1):
                return False
                # Check upper-left diagonal
        i = (row - 1)
        j = (col - 1)
        while ((i >= 0) and (j >= 0)):
            if (board[i][j] == 1):
                return False
            i = (i - 1)
            j = (j - 1)
            # Check upper-right diagonal
        i = (row - 1)
        j = (col + 1)
        while ((i >= 0) and (j < N)):
            if (board[i][j] == 1):
                return False
            i = (i - 1)
            j = (j + 1)
        return True
    def placeQueen(board, row):
        if (row == N):
            solutions.append(__import__('copy').deepcopy(board))
            return
        for col in range(0, N):
            if isSafe(board, row, col):
                board[row][col] = 1
                placeQueen(board, (row + 1))
                board[row][col] = 0
                # Backtrack
    placeQueen(board, 0)
    return solutions
